@import '../../theme.less';

/* 底部 */
.Footer {
    width: 100%;
    height: @footerHeight;
    background: rgba(0, 0, 0, 1);
    color: @fontColor;
    @media (max-width: 767.98px) {
        height: auto;
    }
    .footer-bg {
        width: @contentWidth;
        max-width: @contentMaxWidth;
        margin: auto;
        @media (max-width: 767.98px) {
            width: 100%;
            height: auto;
            padding: 3rem 1rem 2rem;
        }
    }
    .left-content {
        img {
            width: 78px;
            height: 45px;
        }
        p {
            margin-top: 10px;
            color: #fff;
            font-size: 14px;
        }
    }
    .right-content {
        line-height: 85px;
        @media (max-width: 767.98px) {
            line-height: 1.25;
        }
    }
    .info {
        line-height: 60px;
        background: #0a0a0a;
        p {
            font-size: 12px;
            color: #545454;
        }
        @media (max-width: 767.98px) {
            line-height: 1.5;
        }
    }
}
